refentry.refsect1:
&reftitle.description;

 public Yaf_Request_AbstractnullYaf_Dispatcher::getRequest



 Obtém o objeto de requisição mantido pelo despachante.

&reftitle.returnvalues;

 A instância de Yaf_Request_Abstract, ou &null; se a
 aplicação não estiver inicializada.

  &reftitle.examples;

   Exemplo de Yaf_Dispatcher::getRequest


<?php
class IndexController extends Yaf_Controller_Abstract
{
    public function indexAction()
    {
        $request = Yaf_Dispatcher::getInstance()->getRequest();

        // O despachante contém exatamente o mesmo objeto de requisição que é
        // passado ao controlador
        var_dump($request === $this->getRequest());

        return false;
    }
}
?>


   &example.outputs.similar;


bool(true)
